package com.example.microsave.contribution.service;
import com.example.microsave.contribution.entity.Contribution; import com.example.microsave.contribution.dto.ContributionDTO; import com.example.microsave.contribution.repository.ContributionRepository; import com.example.microsave.exception.ResourceNotFoundException; import com.example.microsave.member.repository.MemberRepository; import java.math.BigDecimal; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class ContributionService {private final ContributionRepository repo;private final MemberRepository members;public ContributionService(ContributionRepository r,MemberRepository m){repo=r;members=m;} private Contribution get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Contribution not found: "+id));}private ContributionDTO map(Contribution c){return new ContributionDTO(c.getId(),c.getMember().getId(),c.getAmount(),c.getContributionDate(),c.getWeekNumber(),c.getRemarks());}private void copy(Contribution c,ContributionDTO d){c.setMember(members.findById(d.memberId()).orElseThrow(()->new ResourceNotFoundException("Member not found: "+d.memberId())));c.setAmount(d.amount());c.setContributionDate(d.contributionDate());c.setWeekNumber(d.weekNumber());c.setRemarks(d.remarks());}public List<ContributionDTO> all(){return repo.findAll().stream().map(this::map).toList();}public List<ContributionDTO> byMember(Long id){if(!members.existsById(id))throw new ResourceNotFoundException("Member not found: "+id);return repo.findByMember_Id(id).stream().map(this::map).toList();}public ContributionDTO one(Long id){return map(get(id));}public ContributionDTO save(ContributionDTO d){Contribution c=new Contribution();copy(c,d);return map(repo.save(c));}public ContributionDTO update(Long id,ContributionDTO d){Contribution c=get(id);copy(c,d);return map(repo.save(c));}public void delete(Long id){repo.delete(get(id));}public BigDecimal total(){return repo.totalAll();}public BigDecimal totalForMember(Long id){if(!members.existsById(id))throw new ResourceNotFoundException("Member not found: "+id);return repo.totalByMember(id);}}
